    minesweeper_term_loss: "Поражение",
    minesweeper_rules_loss: "Открытие мины немедленно заканчивает партию — показываются все мины на доске, а та, что сработала, отмечается отдельно от остальных.",
    nonogram_new_game: "Новая головоломка",
